import { Layout, Drawer, Popover, Row, Col, Card, Tabs, Input, Modal, Form, message} from "antd";
import { MenuOutlined } from '@ant-design/icons';
import { Content } from "antd/es/layout/layout";
import React, { useState, useEffect, useRef } from "react";
import TeamSider from "../../components/teamSider";
import './index.css'
import { useSelector, useDispatch } from 'react-redux';
import { openDrawer, closeDrawer } from '../../store/slices/drawerSlice';
import { useTranslation } from "react-i18next";
import '../../locales/i18n'



const Team = () => {
    const [pokemonData, setPokemonData] = useState([]);
    const [pairsList, setPairsList] = useState([]);
    const [curPairsList, setCurPairsList] = useState([])
    const { t, i18n } = useTranslation();

    useEffect(() => {
        const fetchPokemonData = async () => {
            try {
                const response = await fetch(`${process.env.PUBLIC_URL}/data/sync_pairs.json`);
                const data = await response.json();
                setPokemonData(data);
                setPairsList(data)
                setCurPairsList(data)
            } catch (error) {
                console.error('读取拍组失败:', error);
            }
        };

        const fetchEventData = async () => {
            try {
                const response = await fetch(`${process.env.PUBLIC_URL}/data/events.json`);
                const data = await response.json()
                setEventList(data)
            } catch (error) {
                console.error('读取活动失败:', error)
            }
        }

        fetchPokemonData();
        fetchEventData();
    }, []);

    const [eventList, setEventList] = useState([])
    const [currentType, setcurrentType] = useState([])

    const [battleRules, setBattleRules] = useState([])
    const [challengeRules, setChallengeRules] = useState([])
    const [battles, setBattles] = useState([])

    const EventClick = (id) => {
        setcurrentType(eventList.find(item => item.id === id).Type)
        setBattleRules(eventList.find(item => item.id === id).Battle)
        setChallengeRules(eventList.find(item => item.id === id).Challenge)
        setBattles(eventList.find(item => item.id === id).Battles)
    }

    

    useEffect(() => {   
            let Type1 = currentType[0]
            let Type2 = currentType[1]

            const filterList = pokemonData.filter(item => (item.Type === Type1 || item.Type === Type2))
            setPairsList(filterList)
            setCurPairsList(filterList)
        }, [currentType])
    const dispatch = useDispatch();
    const isDrawerOpen = useSelector((state) => state.drawer.isOpen);
    
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedID, setSelectedID] = useState(-1)
    
    const [tabIdx, setTabIdx] = useState(0)
    const none_pair = {
        "id": "",
        "Icon": "/SyncPairs/none pair.png",
        "Label": []
    }
    const [teamPairs, setTeamPairs] = useState({
        0: { "pairOne": none_pair, "pairTwo": none_pair, "pairThree": none_pair},
        1: { "pairOne": none_pair, "pairTwo": none_pair, "pairThree": none_pair},
        2: { "pairOne": none_pair, "pairTwo": none_pair, "pairThree": none_pair},
        3: { "pairOne": none_pair, "pairTwo": none_pair, "pairThree": none_pair},
        4: { "pairOne": none_pair, "pairTwo": none_pair, "pairThree": none_pair}    
    })

    const setVisible = () => {
        setIsModalOpen(false)
    }
    const handleClick = (id) => {
        setSelectedID(id)
        setIsModalOpen(true)
    } 

    const selectPair = ((item) => {
        setVisible()
        if(selectedID == 1) {
            setTeamPairs(prev => ({
                ...prev,
                [tabIdx]: {
                    ...prev[tabIdx],
                    pairOne: item
                }
            }))
        }
        else if(selectedID == 2) {
            setTeamPairs(prev => ({
                ...prev,
                [tabIdx]: {
                    ...prev[tabIdx],
                    pairTwo: item
                }
            }))
        }
        else if(selectedID == 3) {
            setTeamPairs(prev => ({
                ...prev,
                [tabIdx]: {
                    ...prev[tabIdx],
                    pairThree: item
                }
            }))
        }
    })

    const [isChallengeOne, setIsChanllengeOne] = useState(false)
    const [isChallengeTwo, setIsChanllengeTwo] = useState(false)
    
    useEffect(() => {
        if(challengeRules.length == 0) {
            return
        }
        var challengeOne = challengeRules[0]
        setIsChanllengeOne(teamPairs[tabIdx].pairOne?.[challengeOne] || teamPairs[tabIdx].pairTwo?.[challengeOne] || teamPairs[tabIdx].pairThree?.[challengeOne])
        var challengeTwo = challengeRules[1]?.split(" or ")
        setIsChanllengeTwo(teamPairs[tabIdx].pairOne.Label.includes(challengeTwo[0]) || teamPairs[tabIdx].pairOne.Label.includes(challengeTwo[1]) ||
            teamPairs[tabIdx].pairTwo.Label.includes(challengeTwo[0]) || teamPairs[tabIdx].pairTwo.Label.includes(challengeTwo[1]) ||
            teamPairs[tabIdx].pairThree.Label.includes(challengeTwo[0]) || teamPairs[tabIdx].pairThree.Label.includes(challengeTwo[1])
        )
    }, [teamPairs[tabIdx]])


    const [inputValue, setInputValue] = useState(['','','','','']);

    const handleScoreInput = (e) => {
        var value = inputValue[tabIdx]
        if(value == '') return
        value = Number(value.trim())
        if(value >= 0 && value <= 132000) {
            // setInputValue(value.toString()) 
            var temp = inputValue.map((item) => item)
            temp[tabIdx] = value.toString()
            setInputValue(temp)
        }
        else {
            // setInputValue('')      
            var temp = inputValue.map((item) => item)
            temp[tabIdx] = ''
            setInputValue(temp)
            message.error('Invalid score.')
        }
    }

    return (
        <Layout>
            <Content className="teampage" 
                style={{ 
                    background: `url(${process.env.PUBLIC_URL}/background.png) repeat`,
                    backgroundSize: 'auto', 
                    backgroundPosition: 'center',
                    minHeight: '800px',
                    height: `${window.innerHeight - 80}px`,
                    width: '100vw',
                    margin: '0px',
                    // position: 'relative'
                    display: "flex",
                    flexDirection: 'column',
                    alignItems: "center",
                }}
            > 
                
                <div style={{ width: '90%'}}>
                    <ul className="battle-rules-list"
                        style={{ listStyle: 'none', display: "flex", flexDirection: "row", gap: '20px' }}
                    >
                        {
                            battleRules?.map((item) => {
                                return (
                                    <li>
                                        <img src={`${process.env.PUBLIC_URL}${'/Events/' + t(item) + '.png'}`} alt={item}
                                            style={{maxWidth: '100%'}}
                                        />
                                    </li>
                                )
                            })               
                        }
                        { 
                            challengeRules?.map((item) => {
                                return (
                                    <li>
                                        <img src={`${process.env.PUBLIC_URL}${'/Events/' + t(item) + '.png'}`} alt={item}
                                            style={{maxWidth: '100%'}}
                                        />
                                    </li>
                                )
                            })               
                        }
                    </ul>
                </div>
                
                <div style={{
                    display: 'flex',
                    alignItems: 'center'
                }}>
                    <div className="sider-pc"
                        style={{
                        width: '20%',
                    }}>

                        <TeamSider 
                            eventList = {eventList}
                            EventClick = {EventClick}
                        />
                    </div>

                    <div className="container-box" style = {{
                            flex: 1,
                            // width: '95%',
                            // height: '650px',
                            boxSizing: 'border-box',
                            // backgroundColor: 'rgba(58, 169, 255, 0.3)',
                            // position: 'absolute',
                            marginLeft: '2vw',
                            mariginRight: '2vw',
                            marginBottom: '8px',
                            borderRadius: '30px',
                            overflowY: 'auto',
                            // alignSelf: 'center',
                            display: 'flex',
                            justifyContent: 'center'
                        }}>
                            <Tabs  defaultActiveKey="0"
                                type="card"
                                scrollable={true}
                                style={{ width: '90%',
                                
                                }}
                                tabBarStyle={{
                                    margin: 0,
                                    width: '100%', 
                                    display: 'flex',
                                    
                                }}
                                onChange={(activeKey) => {
                                    setTabIdx(Number(activeKey))
                                }}
                                items = {battles?.map((battle, index) => ({
                                    key: String(index),
                                    label: `VS ${t(battle.opponent)}`,
                                    children: (
                                        <div style={{ padding: '8px' }}>
                                            <Row style={{ borderTop: '2px solid #a4a4a4ff',
                                                borderLeft: '2px solid #a4a4a4ff',
                                                borderRight: '2px solid #a4a4a4ff',
                                                borderTopLeftRadius: '8px',
                                                borderTopRightRadius: '8px',
                                                background: '#a3a3a3ff'
                                            }}>
                                                <Col span={24} style={{ 
                                                height: '40px', 
                                                display: 'flex', 
                                                justifyContent: 'center',
                                                alignItems: 'center'
                                                }}>
                                                    
                                                    <Input style={{
                                                        background: 'transparent',
                                                        height: '100%',
                                                        textAlign: 'center',
                                                        fontFamily: "Segoe UI",
                                                        color: '#ffffff',
                                                        fontWeight: 'bold'
                                                    }}
                                                        value={inputValue[tabIdx]}                          
                                                        onChange={(e) => setInputValue(inputValue.map((item, index) => {
                                                            if(index == tabIdx) {
                                                                item = e.target.value
                                                            }

                                                            return item
                                                        }))}
                                                        placeholder={t("Score")}  
                                                        onBlur = {handleScoreInput} 
                                                        onPressEnter = {handleScoreInput} 
                                                    ></Input>
                                                </Col>
                                            </Row>
                                            <Row style={{ borderTop: '2px solid #a4a4a4ff',
                                                    borderLeft: '2px solid #a4a4a4ff',
                                                    borderRight: '2px solid #a4a4a4ff'
                                                }}>
                                                <Col span={12} style={{ 
                                                    borderRight: '2px solid #a4a4a4ff',
                                                    padding: '8px',
                                                    textAlign: 'center',
                                                    background: isChallengeOne ? '#64ff9fff': '#ff5252ff'
                                                }}>
                                                {t(challengeRules[0])}
                                                </Col>
                                                <Col span={12} style={{ 
                                                    // borderRight: '2px solid #a4a4a4ff',
                                                    padding: '8px',
                                                    textAlign: 'center',
                                                    background: isChallengeTwo ? '#64ff9fff': '#ff5252ff'
                                                }}>
                                                {t(challengeRules[1])}
                                                </Col>
                                                
                                            </Row>
                                            <Row style={{ borderTop: '2px solid #a4a4a4ff',
                                                borderLeft: '2px solid #a4a4a4ff',
                                                borderRight: '2px solid #a4a4a4ff'
                                            }}>
                                                <Col span={24} style={{ 
                                                height: '120px', 
                                                display: 'flex', 
                                                justifyContent: 'center',
                                                alignItems: 'center',
                                                background: '#ffffff'
                                                }}>
                                                <img 
                                                    src={`${process.env.PUBLIC_URL}${'/Events/' + battle.opponent + '.png'}`} 
                                                    alt={battle.opponent}
                                                    style={{ 
                                                        maxHeight: '100%',
                                                        maxWidth: '100%',
                                                        objectFit: 'contain'
                                                    }}
                                                />
                                                </Col>
                                            </Row>

                                            <Row style={{ borderTop: '2px solid #a4a4a4ff',
                                                    borderLeft: '2px solid #a4a4a4ff',
                                                    borderRight: '2px solid #a4a4a4ff',
                                                    height: '120px'
                                                }}>
                                                <Col span={8} style={{ 
                                                    borderRight: '2px solid #a4a4a4ff',
                                                    padding: '8px',
                                                    textAlign: 'center',
                                                    background: '#ffffffff',
                                                    height: '100%',
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    justifyContent: 'center'
                                                }}>
                                                    <img src={`${process.env.PUBLIC_URL}${'/Pokemon/' + battle.pokemon[0] + '.png'}`}
                                                        style={{
                                                            maxHeight: '100%',
                                                            maxWidth: '100%',
                                                            objectFit: 'contain',
                                                            marginLeft: '10px'
                                                        }}
                                                    />
                                                </Col>
                                                <Col span={8} style={{ 
                                                    borderRight: '2px solid #a4a4a4ff',
                                                    padding: '8px',
                                                    textAlign: 'center',
                                                    background: '#ffffffff',
                                                    height: '100%',
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    justifyContent: 'center'
                                                }}>
                                                    <img src={`${process.env.PUBLIC_URL}${'/Pokemon/' + battle.pokemon[1] + '.png'}`}
                                                        style={{
                                                            maxHeight: '100%',
                                                            maxWidth: '100%',
                                                            objectFit: 'contain',
                                                            marginLeft: '10px'
                                                        }}
                                                    />
                                                </Col>
                                                <Col span={8} style={{ 
                                                    padding: '8px',
                                                    textAlign: 'center',
                                                    background: '#ffffffff',
                                                    height: '100%',
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    justifyContent: 'center'
                                                }}>
                                                    <img src={`${process.env.PUBLIC_URL}${'/Pokemon/' + battle.pokemon[2] + '.png'}`}
                                                        style={{
                                                            maxHeight: '100%',
                                                            maxWidth: '100%',
                                                            objectFit: 'contain',
                                                            marginLeft: '10px'
                                                        }}
                                                    />
                                                </Col>
                                            </Row>
                                            
                                            <Row style={{ borderTop: '2px solid #a4a4a4ff',
                                                    borderLeft: '2px solid #a4a4a4ff',
                                                    borderRight: '2px solid #a4a4a4ff',
                                                    height: '40px'
                                                }}>
                                                <Col span={8} style={{ 
                                                    borderRight: '2px solid #a4a4a4ff',
                                                    padding: '8px',
                                                    textAlign: 'center',
                                                    background: '#84caffff',
                                                    height: '100%',
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    justifyContent: 'center'
                                                }}>
                                                    <p>{t('Weakness')}: </p>
                                                    <img src={`${process.env.PUBLIC_URL}${'/Types/' + battle.weakness[0] + '.png'}`}
                                                        style={{
                                                            maxHeight: '100%',
                                                            maxWidth: '100%',
                                                            objectFit: 'contain',
                                                            marginLeft: '10px'
                                                        }}
                                                    />
                                                </Col>
                                                <Col span={8} style={{ 
                                                    borderRight: '2px solid #a4a4a4ff',
                                                    padding: '8px',
                                                    textAlign: 'center',
                                                    background: '#84caffff',
                                                    height: '100%',
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    justifyContent: 'center'
                                                }}>
                                                    <p>{t('Weakness')}: </p>
                                                    <img src={`${process.env.PUBLIC_URL}${'/Types/' + battle.weakness[1] + '.png'}`}
                                                        style={{
                                                            maxHeight: '100%',
                                                            maxWidth: '100%',
                                                            objectFit: 'contain',
                                                            marginLeft: '10px'
                                                        }}
                                                    />
                                                </Col>
                                                <Col span={8} style={{ 
                                                    padding: '8px',
                                                    textAlign: 'center',
                                                    background: '#84caffff',
                                                    height: '100%',
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    justifyContent: 'center'
                                                }}>
                                                    <p>{t('Weakness')}: </p>
                                                    <img src={`${process.env.PUBLIC_URL}${'/Types/' + battle.weakness[2] + '.png'}`}
                                                        style={{
                                                            maxHeight: '100%',
                                                            maxWidth: '100%',
                                                            objectFit: 'contain',
                                                            marginLeft: '10px'
                                                        }}
                                                    />
                                                </Col>
                                            </Row>

                                            <Row style={{ borderTop: '2px solid #a4a4a4ff',
                                                    borderLeft: '2px solid #a4a4a4ff',
                                                    borderRight: '2px solid #a4a4a4ff',
                                            }}>
                                                <Col span={24} style={{ 
                                                    display: 'flex', 
                                                    justifyContent: 'center',
                                                    alignItems: 'center',
                                                    background: '#f7d31dff'
                                                }}>
                                                    <p>{t('Sync Move')}:</p>
                                                    <img src={`${process.env.PUBLIC_URL}${'/' + battle.syncmove + '.png'}`}
                                                        style={{
                                                            maxHeight: '100%',
                                                            maxWidth: '100%',
                                                            objectFit: 'contain',
                                                            marginLeft: '10px'
                                                        }}
                                                    />
                                                </Col>
                                            </Row>

                                            <Row style={{ border: '2px solid #a4a4a4ff',
                                                borderBottomLeftRadius: '8px',
                                                borderBottomRightRadius: '8px'
                                            }}>
                                                <Col span={24} style={{ 
                                                    display: 'flex', 
                                                    justifyContent: 'center',
                                                    alignItems: 'center',
                                                    background: '#f7d31dff'
                                                }}>
                                                { t(battle.rule) }
                                                </Col>
                                            </Row>

                                            <Row style={{ 
                                                maxHeight: '30%'
                                                }}>
                                                <Col span={8} style={{ 
                                                    padding: '8px',
                                                    textAlign: 'center'
                                                }}>
                                                    <img 
                                                        src={`${process.env.PUBLIC_URL}${teamPairs[tabIdx].pairOne.Icon}`} 
                                                        alt={battle.opponent}
                                                        style={{ 
                                                            height: '60%',
                                                            width: '60%',
                                                            minWidth: '160px',
                                                            objectFit: 'contain',
                                                            cursor: 'pointer'
                                                        }}
                                                        onClick={ () => handleClick(1) }
                                                    />
                                                </Col>
                                                <Col span={8} style={{ 
                                                    padding: '8px',
                                                    textAlign: 'center'
                                                }}>
                                                    <img 
                                                        src={`${process.env.PUBLIC_URL}${teamPairs[tabIdx].pairTwo.Icon}`} 
                                                        alt={battle.opponent}
                                                        style={{ 
                                                            height: '60%',
                                                            width: '60%',
                                                            minWidth: '160px',
                                                            objectFit: 'contain',
                                                            cursor: 'pointer'
                                                        }}
                                                        onClick={ () => handleClick(2) }
                                                    />
                                                </Col>
                                                <Col span={8} style={{ 
                                                    padding: '8px',
                                                    textAlign: 'center'
                                                }}>
                                                    <img 
                                                        src={`${process.env.PUBLIC_URL}${teamPairs[tabIdx].pairThree.Icon}`} 
                                                        alt={battle.opponent}
                                                        style={{ 
                                                            height: '60%',
                                                            width: '60%',
                                                            minWidth: '160px',
                                                            objectFit: 'contain',
                                                            cursor: 'pointer'
                                                        }}
                                                        onClick={ () => handleClick(3) }
                                                    />
                                                </Col>
                                            </Row>
                                        </div>
                                    ),
                                }))}
                            >
                                
                            </Tabs>
                    </div>
                </div>
                
                

                

                <Drawer className="sider-mobile" 
                        styles={{
                            header: {
                                background: `url(${process.env.PUBLIC_URL}/header.png)`
                            },
                            body: {
                                background: `url(${process.env.PUBLIC_URL}/background.png) repeat`, // ✅ 渐变背景
                                padding: '20px'
                            },
                            content: {
                                backgroundColor: 'transparent' // ✅ 内容区域透明
                            }
                        }}
                    
                    onClose={() => dispatch(closeDrawer())}
                    open={isDrawerOpen}
                >
                    <TeamSider 
                        eventList = {eventList}
                        EventClick = {EventClick}
                    />
                </Drawer>

                <Modal
                    title={t("Sync Pairs")}   // 可动态改
                    open={isModalOpen}
                    onCancel={() => setVisible(false)}
                    footer={null}
                    
                    >
                    <div className="container-box"
                        style = {{
                            // width: '75%',
                            flex: 1,
                            height: '70vh',
                            // maxHeight: '600px',
                            boxSizing: 'border-box',
                            // backgroundColor: 'rgba(58, 169, 255, 0.3)',
                            // position: 'absolute',
                            marginLeft: '2vw',
                            mariginRight: '2vw',
                            marginBottom: '1vh',
                            borderRadius: '30px',
                            overflowY: 'auto',
                            alignSelf: 'center'
                        }}>
                        <div style={{
                            display: 'grid',
                        
                            gridTemplateColumns: 'repeat(auto-fill, minmax(100px, 1fr))',
                            
                            // gridTemplateRows: 'repeat(5, 100px)',   // 5行，每行100px
                            gap: '1vw',
                            padding: '2%'
                        }}>
                            {
                                curPairsList.filter((item) => {
                                    return item.id != teamPairs[tabIdx].pairOne.id && item.id != teamPairs[tabIdx].pairTwo.id 
                                        && item.id != teamPairs[tabIdx].pairThree.id
                                }).map(item => {
                                    return (
                                        <div
                                            key={item.id}
                                            // onClick={() => handleIconClick(item)}
                                            style={{
                                                display: 'flex',
                                                alignItems: 'center',
                                                justifyContent: 'center',
                                                boxSizing: 'border-box',
                                                maxWidth: "100px",
                                                cursor: "pointer"
                                            }}
                                            
                                            >
                                                <img src={`${process.env.PUBLIC_URL}${item.Icon}`} alt='icon' style={{
                                                    width: '120%',    
                                                    height: '120%',
                                                    objectFit: 'contain',  
                                                    }}
                                                onClick = { () => selectPair(item) }></img>
                                        </div>
                                    )
                                })
                            }
                        </div>
    
                        
                    </div>
                </Modal>
            </Content>
        </Layout>
    )
}

export default Team