import { Layout, Drawer, Popover} from "antd";
import { MenuOutlined } from '@ant-design/icons';
import { Content } from "antd/es/layout/layout";
import React, { useState, useEffect } from "react";
import CommonSider from "../../components/commonSider";
import './index.css'
import { useSelector, useDispatch } from 'react-redux';
import { openDrawer, closeDrawer } from '../../store/slices/drawerSlice';
import { useTranslation } from "react-i18next";
import '../../locales/i18n'
import en from '../../locales/en.json'


const Home =() => {
    const [pokemonData, setPokemonData] = useState([]);
    const [pairsList, setPairsList] = useState([]);
    const [curPairsList, setCurPairsList] = useState([])

    const [eventList, setEventList] = useState([])
    const [selectedOptionOne, setSelectedOptionOne] = useState('All');
    const [selectedOptionTwo, setSelectedOptionTwo] = useState('All');

    const [currentType, setcurrentType] = useState([])

    const [modalVisible, setModalVisible] = useState(false)
    const [selectedItem, setSelectedItem] = useState(null)

    const dispatch = useDispatch();
    const isDrawerOpen = useSelector((state) => state.drawer.isOpen);

    const { t, i18n } = useTranslation();

    useEffect(() => {
        const fetchPokemonData = async () => {
            try {
                const response = await fetch(`${process.env.PUBLIC_URL}/data/sync_pairs.json`);
                const data = await response.json();
                setPokemonData(data);
                setPairsList(data)
                setCurPairsList(data)
            } catch (error) {
                console.error('读取拍组失败:', error);
            }
        };

        const fetchEventData = async () => {
            try {
                const response = await fetch(`${process.env.PUBLIC_URL}/data/events.json`);
                const data = await response.json()
                setEventList(data)
            } catch (error) {
                console.error('读取活动失败:', error)
            }
        }

        fetchPokemonData();
        fetchEventData();
    }, []);
    
    // console.log(pokemonData)
    
    useEffect(() => {
        console.log(pairsList)
        setCurPairsList(pairsList.filter(item => (item[selectedOptionOne] === true || selectedOptionOne === '') 
            && (item['Label'].some(i => i === selectedOptionTwo) || selectedOptionTwo === '')))
    }, [selectedOptionOne, selectedOptionTwo])

    const EventClick = (id) => {
        setcurrentType(eventList.find(item => item.id === id).Type)
    }

    useEffect(() => {
        setSelectedOptionOne('')
        setSelectedOptionTwo('')
        
        let Type1 = currentType[0]
        let Type2 = currentType[1]
        console.log(Type1 + " " + Type2)
        const filterList = pokemonData.filter(item => (item.Type === Type1 || item.Type === Type2))
        setPairsList(filterList)
        setCurPairsList(filterList)
        console.log(curPairsList)
    }, [currentType])

    const translateTerm = (text) => {
        // 定义所有需要翻译的术语（和语言包 key 完全一致）
        const terms = Object.keys(en)

        let translated = text;

        terms.forEach(term => {
        // 创建不区分大小写的全局正则（忽略多余空格）
        const regex = new RegExp(term.replace(/([.*+?^${}()|[\]\\])/g, '\\$&'), 'g');
            translated = translated.replace(regex, (matched) => {
                // 用标准 key 去 t() 翻译（保证大小写一致）
                return t(term, { defaultValue: matched });
            });
        });

        return translated;
    };

    const renderPopoverContent = (item) => (
        <div style={{ width: 280, padding: 8 }}>
            <div style={{ textAlign: 'center', marginBottom: 12 }}>
                <img 
                    src={`${process.env.PUBLIC_URL}${item.Icon}`} 
                    alt="预览" 
                    style={{ width: 60, height: 60 }}
                />
                <h4 style={{ margin: '8px 0' }}>{t(item.Trainer) + ' & ' + t(item.Pokemon)}</h4>
            </div>
            <div style={{ background: '#f5f5f5', padding: 12, borderRadius: 6, whiteSpace: 'pre-line'}}>
                {translateTerm(item.Description)}
            </div>
        </div>
    );

    
    return (
        <Layout>
            <Content className="homepage" 
                style={{ 
                    background: `url(${process.env.PUBLIC_URL}/background.png) repeat`,
                    backgroundSize: 'auto', 
                    backgroundPosition: 'center',
                    minHeight: '800px',
                    height: `${window.innerHeight - 80}px`,
                    width: '100vw',
                    margin: '0px',
                    // position: 'relative'
                    display: "flex",
                    justifyContent: "center",
                }}
            > 
                <div className="sider-pc"
                    style={{
                    width: '20%',
                    alignSelf: 'flex-start'
                }}>
                    <CommonSider 
                        selectedOptionOne = {selectedOptionOne}
                        selectedOptionTwo = {selectedOptionTwo}
                        setSelectedOptionOne = {setSelectedOptionOne}
                        setSelectedOptionTwo = {setSelectedOptionTwo}
                        eventList = {eventList}
                        EventClick = {EventClick}
                    />
                </div>

                

                <Drawer className="sider-mobile" 
                        styles={{
                            header: {
                                background: `url(${process.env.PUBLIC_URL}/header.png)`
                            },
                            body: {
                                background: `url(${process.env.PUBLIC_URL}/background.png) repeat`, // ✅ 渐变背景
                                padding: '20px'
                            },
                            content: {
                                backgroundColor: 'transparent' // ✅ 内容区域透明
                            }
                        }}
                    
                    onClose={() => dispatch(closeDrawer())}
                    open={isDrawerOpen}
                >
                    <CommonSider 
                        selectedOptionOne = {selectedOptionOne}
                        selectedOptionTwo = {selectedOptionTwo}
                        setSelectedOptionOne = {setSelectedOptionOne}
                        setSelectedOptionTwo = {setSelectedOptionTwo}
                        eventList = {eventList}
                        EventClick = {EventClick}
                    />
                </Drawer>
                
                
                <div className="container-box"
                    style = {{
                        // width: '75%',
                        flex: 1,
                        height: '90%',
                        maxHeight: '80vh',
                        boxSizing: 'border-box',
                        backgroundColor: 'rgba(58, 169, 255, 0.3)',
                        // position: 'absolute',
                        marginLeft: '2vw',
                        mariginRight: '2vw',
                        marginBottom: '1vh',
                        borderRadius: '30px',
                        overflowY: 'auto',
                        alignSelf: 'center'
                    }}>
                    <div style={{
                        display: 'grid',
                    
                        gridTemplateColumns: 'repeat(auto-fill, minmax(100px, 1fr))',
                        
                        // gridTemplateRows: 'repeat(5, 100px)',   // 5行，每行100px
                        gap: '1vw',
                        padding: '2%'
                    }}>
                        {
                            curPairsList.map(item => {
                                return (<Popover
                                    key={item.id}
                                    content={renderPopoverContent(item)}
                                    trigger="click"
                                    placement="bottom"
                                    style={{
                                        maxWidth: '400px' // 控制弹窗最大宽度
                                    }}
                                > 
                                    <div
                                        key={item.id}
                                        // onClick={() => handleIconClick(item)}
                                        style={{
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            boxSizing: 'border-box',
                                            maxWidth: "100px",
                                            cursor: "pointer"
                                        }}
                                        
                                        >
                                            <img src={`${process.env.PUBLIC_URL}${item.Icon}`} alt='icon' style={{
                                                width: '120%',    
                                                height: '120%',
                                                objectFit: 'contain', 
                                            }}></img>
                                    </div>
                                </Popover>)
                            })
                        }
                    </div>

                    
                </div>
                
                
                
            </Content>
        </Layout>
        
        
    )
}

export default Home;