import React from "react";
import { Layout, Card, Select, Space} from "antd";
const { Option } = Select;

const TeamSider = ({eventList, EventClick}) => {
    return (
        <div className="menu" style={{ width: '100% '}}>
            <ul className="event-list"
                style={{
                    height: '80%',
                    overflowY: 'auto',           
                    overflowX: 'hidden',         
                    scrollbarWidth: 'thin',      
                    scrollbarColor: '#c0c0c0 transparent', 

                    WebkitOverflowScrolling: 'touch',

                    padding: '0',  
                    margin: '0 auto',  
                    display: 'flex',  
                    flexDirection: 'column',  
                    alignItems: 'center',  
                    listStyle: 'none',  
                    width: '100%',  
                    marginTop: "5%"
                }}
            >
                {
                    eventList?.map(item => {
                        return (
                            <li style={{
                                overflow: "hidden",
                                cursor: 'pointer'
                                }}
                                onClick={() => EventClick(item.id)}                                   
                            >
                                <img src={`${process.env.PUBLIC_URL}${item.Icon}`} alt="eventIcon"
                                    style = {{
                                        width: '100%',
                                        height: 'auto',
                                        objectFit: 'cover',
                                        display: 'block',
                                        margin: '5px'
                                    }}
                                ></img>
                            </li>
                        )
                    })
                }
            </ul>
        </div>
    )
}


export default TeamSider;