import {React, useRef, useState} from "react";
import './index.css'
import { useSelector, useDispatch } from 'react-redux';
import { openDrawer, closeDrawer } from '../../store/slices/drawerSlice';
import { Layout, Menu, Dropdown, Button, Modal, Select} from "antd";
import { MenuOutlined, MoreOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import { Grid } from 'antd';
import { useTranslation } from "react-i18next";
import '../../locales/i18n'


const { useBreakpoint } = Grid;


const {Header} = Layout

const CommonHeader = () => {
    const navigate = useNavigate()
    const containerRef = useRef();
    const dispatch = useDispatch();

    const { t, i18n } = useTranslation();

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [tempLng, setTempLng] = useState('en')

    const showModal = () => {
        setIsModalOpen(true);
    };

    const handleOk = () => {
        setIsModalOpen(false);
        i18n.changeLanguage(tempLng)
    };

    const handleCancel = () => {
        setIsModalOpen(false);
    };


    const items = [
        {key: '1', label: t('Home'), onClick: () => navigate('/home')},
        {key: '2', label: t('Team'), onClick: () => navigate('/team')},
        {key: '3', label: t('Settings'), onClick: showModal}
    ]
    function isMobile() {
        return window.innerWidth <= 768;
    }
    

    return (
        <Layout>
            <Header className='header' style={{  height: '80px',
                background: `url(${process.env.PUBLIC_URL}/header.png)`,
            }}>
                <div className="sider-button-mobile" style={{ width: '10vw'}}>
                    <Button 
                        icon={<MenuOutlined />} 
                        onClick={() => dispatch(openDrawer())}
                        className="menu-button"
                        ghost 
                    ></Button>
                </div>
                
                <div style={{ width: '100%'}}>
                    <div style={{display: 'flex', alignItems: 'center', height: '80px', justifyContent: 'center'}}>
                        <div className="logo"
                            style={{ display: 'flex', alignItems: 'flex-start', width: '25%'}}>
                            <img className="logo-image"
                            src = {`${process.env.PUBLIC_URL}/icon.png`} 
                            alt = 'logo' 
                            style={{
                                    height: '64px',  // 使用 style 对象
                                    width: 'auto'
                                }}>
                            </img>
                            
                        </div>
                        <div style={{ 
                            color: 'white', 
                            fontSize: 'clamp(8px, 20px, 20px)',
                            fontWeight: '700',
                            marginRight: '2vw',
                            background: 'linear-gradient(45deg, #fff, #a8d8ff)',
                            WebkitBackgroundClip: 'text',
                            WebkitTextFillColor: 'transparent',
                            whiteSpace: 'nowrap',
                            width: '70%',
                            // height:'64px',
                            display: ' flex',
                            justifyContent: 'center'
                        }}>
                            {t('High Score Event Tool')}
                        </div>
                        <div 
                            ref={containerRef}
                            style={{ 
                                width: '20%',
                                
                                margin: '0 auto',
                                display: 'flex',
                                justifyContent: 'flex-end'
                            }}
                            >
                            <Dropdown
                                menu={{ items }} 
                                trigger={['click']}  
                                placement="bottomRight" 
                                getPopupContainer={() => containerRef.current} 
                                overlayStyle={{ minWidth: '120px' }} 
                            >
                                <div style={{
                                display: 'inline-flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                width: '40px',  
                                height: '40px',
                                border: '1px solid #ffffff',
                                borderRadius: '6px',
                                background: 'transparent',
                                color: '#ffffff',
                                fontSize: '18px',
                                cursor: 'pointer', 
                                }}>
                                <MoreOutlined />
                                </div>
                            </Dropdown>
                            
                        </div>
                    </div>
                </div>

                <Modal
                    title={t("Settings")}   // 可动态改
                    open={isModalOpen}
                    onOk={handleOk}
                    onCancel={handleCancel}
                    okText="OK"
                    cancelText="Cancel"
                    >
                    <Select 
                        defaultValue="en"               // 默认选中值
                        style={{ width: '120px' }}
                        onChange={(value) => {setTempLng(value)}}
                        options={[
                            { value: 'en', label: 'English' },
                            { value: 'zh', label: '中文' },
                            { value: 'ja', label: '日本語' },
                    ]}/>
                </Modal>
                
                
                    
            </Header>
        </Layout>
    )
}

export default CommonHeader;