import React from "react";
import { Layout, Card, Select, Space, Menu} from "antd";
import { useNavigate } from 'react-router-dom';
import { useTranslation } from "react-i18next";
import '../../locales/i18n'



const { Option } = Select;

const CommonSider = ({selectedOptionOne, selectedOptionTwo, setSelectedOptionOne, setSelectedOptionTwo, eventList, EventClick}) => {
    const { t, i18n } = useTranslation();

    return (
        <div className="menu" style={{ width: '100% '}}>
            <div direction="vertical" 
                size={4} 
                // align= "center"
                style={{ 
                    // position: 'absolute',
                    width: '100%',
                    zIndex: 10,
                    display: "flex",
                    justifyContent: "center"
               
            }}>
                <Select
                    value={selectedOptionOne}
                    onChange={setSelectedOptionOne}
                    
                    style={{ width: '100%', height: '3.5vh', marginTop: '8%'}}
                    >
                    <Option value="">{t('All')}</Option> 
                    <Option value="Confusion">{t('Confusion')}</Option>
                    <Option value="Trap">{t('Trap')}</Option>
                    <Option value="Flinch">{t('Flinch')}</Option>
                    <Option value="Poison">{t('Poison')}</Option>
                    <Option value="Burn">{t('Burn')}</Option>
                    <Option value="Sleep">{t('Sleep')}</Option>
                    <Option value="Paralysis">{t('Paralysis')}</Option>
                    <Option value="Freeze">{t('Freeze')}</Option>
                </Select>
                <Select
                    value={selectedOptionTwo}
                    onChange={setSelectedOptionTwo}
                    
                    style={{ width: '100%', height: '3.5vh', marginTop: '8%'}}
                    >
                    <Option value="">{t('All')}</Option> 
                    <Option value="Main Character">{t('Main Character')}</Option>
                    <Option value="Rival">{t('Rival')}</Option>
                    <Option value="Champion">{t('Champion')}</Option>
                    <Option value="Gym Leader">{t('Gym Leader')}</Option>
                </Select>
            </div>
            
            <ul className="event-list"
                style={{
                    height: '80%',
                    overflowY: 'auto',           
                    overflowX: 'hidden',         
                    scrollbarWidth: 'thin',      
                    scrollbarColor: '#c0c0c0 transparent', 

                    WebkitOverflowScrolling: 'touch',

                    padding: '0',  
                    margin: '0 auto',  
                    display: 'flex',  
                    flexDirection: 'column',  
                    alignItems: 'center',  
                    listStyle: 'none',  
                    width: '100%',  
                    marginTop: "5%"
                }}
            >
                {
                    eventList?.map(item => {
                        return (
                            <li style={{
                                overflow: "hidden",
                                cursor: 'pointer'
                                }}
                                onClick={() => EventClick(item.id)}                                   
                            >
                                <img src={`${process.env.PUBLIC_URL}${item.Icon}`} alt="eventIcon"
                                    style = {{
                                        width: '100%',
                                        height: 'auto',
                                        objectFit: 'cover',
                                        display: 'block',
                                        margin: '5px'
                                    }}
                                ></img>
                            </li>
                        )
                    })
                }
            </ul>
        </div>
    )
}


export default CommonSider;